package com.hbm.machine.coker;
import com.google.gson.*;
import com.hbm.fluid.*;
import com.hbm.hazard.HbmHazards;
import com.hbm.material.MaterialDistributionConfig;
import com.hbm.recipe.generic.*;
import com.mojang.logging.LogUtils;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.TagParser;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.item.crafting.*;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.fml.loading.FMLPaths;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.OnDatapackSyncEvent;
import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;
/** Source33defaults and hbmCoker.json fullreplacement;actualruntime fueltraits calculate auto quantities before native RecipeManager sync. */
public final class CokerRecipeConfig {
 private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();private static final Map<String,String> ALIASES=new LinkedHashMap<>();private static final List<String> UNRESOLVED=new ArrayList<>();
 public static void register(){try(var stream=CokerRecipeConfig.class.getResourceAsStream("/hbm/coker-item-aliases.json")){if(stream==null)throw new IllegalStateException("Missing coker aliases");JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet().forEach(e->ALIASES.put(e.getKey(),e.getValue().getAsString()));}catch(Exception error){throw new IllegalStateException(error);}NeoForge.EVENT_BUS.addListener((ServerAboutToStartEvent e)->install(e.getServer()));NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(OnDatapackSyncEvent e)->{var server=e.getPlayerList().getServer();if(e.getPlayer()==null||!INSTALLED.containsKey(server.getRecipeManager()))install(server);});}
 public static List<CokerRecipe> recipes(RecipeManager manager){return manager.getAllRecipesFor(CokerContent.TYPE.get()).stream().map(RecipeHolder::value).sorted(Comparator.comparingInt(r->r.data().order())).toList();}public static CokerRecipe find(RecipeManager manager,HbmFluidType input){var rows=recipes(manager);for(int i=rows.size()-1;i>=0;i--)if(rows.get(i).input().type==input)return rows.get(i);return null;}public static List<String> unresolved(){return List.copyOf(UNRESOLVED);}
 private static void install(MinecraftServer server){var manager=server.getRecipeManager();var old=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var holder:manager.getOrderedRecipes())if(old.get(holder.id())!=holder)merged.put(holder.id(),holder);var added=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();UNRESOLVED.clear();Path dir=FMLPaths.CONFIGDIR.get().resolve("hbmRecipes"),active=dir.resolve("hbmCoker.json");boolean custom=Files.isRegularFile(active);try{Files.createDirectories(dir);JsonObject root;if(custom){merged.values().removeIf(h->h.value().getType()==CokerContent.TYPE.get());try(var reader=Files.newBufferedReader(active)){root=JsonParser.parseReader(reader).getAsJsonObject();}}else{try(var stream=CokerRecipeConfig.class.getResourceAsStream("/hbm/coker-defaults.json")){if(stream==null)throw new IllegalStateException("Missing source33cokerdefaults");root=JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();}}int order=0;for(var value:root.getAsJsonArray("recipes")){try{var row=value.getAsJsonObject();var recipe=!custom&&row.has("autoTU")?automatic(row,order):legacy(row,order);added.values().removeIf(h->((CokerRecipe)h.value()).input().type==recipe.input().type);var id=ResourceLocation.parse("hbm:coker/"+(custom?"config/":"default/")+order);added.put(id,new RecipeHolder<>(id,recipe));}catch(Exception error){UNRESOLVED.add("row "+order+": "+error.getMessage());}order++;}if(!custom)template(dir.resolve("_hbmCoker.json"),added.values().stream().map(h->(CokerRecipe)h.value()).toList());}catch(Exception error){LogUtils.getLogger().error("Cannot load actualCoker recipe replacement",error);}added.forEach(merged::put);manager.replaceRecipes(merged.values());INSTALLED.put(manager,added);if(!UNRESOLVED.isEmpty())LogUtils.getLogger().error("Actual Coker recipes unresolved: {}",UNRESOLVED);}
 private static CokerRecipe automatic(JsonObject row,int order)throws Exception{var input=fluid(row.get("fluid").getAsString());var flame=input.getTrait(FluidTraits.Flammable.class);var combustion=input.getTrait(FluidTraits.Combustible.class);long perBucket=Math.max(flame==null?0:flame.getHeatEnergy(),combustion==null?0:combustion.getCombustionEnergy());int amount=(int)(row.get("autoTU").getAsLong()*1000L*1D/perBucket);if(amount>10000)amount-=amount%1000;else if(amount>1000)amount-=amount%100;else if(amount>100)amount-=amount%10;var byproduct=row.has("byproductType")?new FluidStack(fluid(row.get("byproductType").getAsString()),Math.max(10,amount/10)):null;return create(new FluidStack(input,amount),row.has("output")?stack(row.getAsJsonArray("output")):ItemStack.EMPTY,byproduct,order);}
 private static CokerRecipe legacy(JsonObject row,int order)throws Exception{return create(readFluid(row.getAsJsonArray("input")),row.has("output")?stack(row.getAsJsonArray("output")):ItemStack.EMPTY,row.has("byproduct")?readFluid(row.getAsJsonArray("byproduct")):null,order);}
 private static CokerRecipe create(FluidStack input,ItemStack output,FluidStack byproduct,int order){var data=new GenericRecipeData("coker."+input.type.getName(),0,0,List.of(),List.of(input),output.isEmpty()?List.of():List.of(new GenericOutput(output)),byproduct==null?List.of():List.of(byproduct),List.of(),"",ItemStack.EMPTY,false,"",order);return new CokerRecipe(data);}
 private static HbmFluidType fluid(String name){var type=HbmFluids.fromName(name);if(type==HbmFluids.NONE&&!name.equals("NONE"))throw new IllegalArgumentException("Unregistered original fluid "+name);return type;}private static FluidStack readFluid(JsonArray a){return new FluidStack(fluid(a.get(0).getAsString()),a.get(1).getAsInt(),a.size()>2?a.get(2).getAsInt():0);}
 private static ItemStack stack(JsonArray spec)throws Exception{String name=spec.get(0).getAsString();int metadata=spec.size()>2?spec.get(2).getAsInt():0;String target=ALIASES.getOrDefault(name,name);if(target.equals("minecraft:coal")&&metadata==1){target="minecraft:charcoal";metadata=0;}var stack=MaterialDistributionConfig.legacyStack(target,metadata);if(stack.isEmpty())throw new IllegalArgumentException("Unregistered original item "+name);stack.setCount(spec.size()>1?spec.get(1).getAsInt():1);if(spec.size()>3)stack.set(DataComponents.CUSTOM_DATA,CustomData.of(TagParser.parseTag(spec.get(3).getAsString())));return stack;}
 private static JsonArray array(Object... values){var out=new JsonArray();for(var value:values)if(value instanceof Number number)out.add(number);else out.add(value.toString());return out;}private static JsonArray fluidJson(FluidStack fluid){return fluid.pressure==0?array(fluid.type.getName(),fluid.fill):array(fluid.type.getName(),fluid.fill,fluid.pressure);}private static JsonArray itemJson(ItemStack stack){var out=array(BuiltInRegistries.ITEM.getKey(stack.getItem()).toString(),stack.getCount(),stack.getOrDefault(HbmHazards.LEGACY_METADATA.get(),stack.getDamageValue()));if(stack.has(DataComponents.CUSTOM_DATA))out.add(stack.get(DataComponents.CUSTOM_DATA).copyTag().toString());return out;}
 private static void template(Path path,List<CokerRecipe> recipes)throws Exception{var root=new JsonObject();var rows=new JsonArray();for(var recipe:recipes){var row=new JsonObject();row.add("input",fluidJson(recipe.input()));if(!recipe.solid().isEmpty())row.add("output",itemJson(recipe.solid()));if(recipe.byproduct()!=null)row.add("byproduct",fluidJson(recipe.byproduct()));rows.add(row);}root.add("recipes",rows);Files.writeString(path,new GsonBuilder().setPrettyPrinting().create().toJson(root)+"\n");}private CokerRecipeConfig(){}
}
